   require(d.pin(j.at("source_packet"),base)==std::filesystem::absolute(path)&&j.at("source_packet").at("sha256")==p.source_hash,"native measurement revision exact packet");d.pin(j.at("issuer"),base);
   const auto parent_file=d.pin(j.at("parent_packet"),base);std::unique_ptr<Packet> owner;const auto&parent=verified_parent?*verified_parent:*(owner=std::make_unique<Packet>(joint_effective_packet_generation_v1<Packet>(parent_file.u8string(),m,0)));
   const auto revision_file=d.pin(j.at("revision"),base);const auto revision=eventio::read_json(revision_file);
