   const auto parent_file=d.pin(j.at("parent_packet"),base);std::unique_ptr<Packet> owner;const auto&parent=verified_parent?*verified_parent:*(owner=std::make_unique<Packet>(joint_effective_packet_generation_v1<Packet>(parent_file.u8string(),m,0)));
